// Real generated bytes/ZIP; Node checks do not establish private hosting or teacher validation.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),{execFileSync}=require('node:child_process');
const Staff=require('../scripts/build-staff-review.cjs'),SC=require('../src/school/config.js'),PK=require('../src/school/package.js');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
(async()=>{
 const a=await Staff.prepare(),b=await Staff.prepare();assert.deepEqual(a.files,b.files);
 assert.equal(a.manifest.sourceCommit,execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim());
 assert.equal(a.manifest.pupilRelease,'BLOCKED');assert.equal(a.manifest.humanValidation,'PENDING');assert.equal(a.manifest.accessControl,'REQUIRED_AT_HOST_NOT_INCLUDED');
 assert(String(a.files['LES-MEG.txt']).includes(a.manifest.sourceCommit));assert(String(a.files['LES-MEG.txt']).includes(a.manifest.appCandidateHash));
 const expected=['index.html','nn.html','nb.html','en.html','school-settings.json','sounds/ATTRIBUTION.txt','sounds/C3.mp3','sounds/C4.mp3','sounds/C5.mp3','sounds/Fs3.mp3','sounds/Fs4.mp3','LES-MEG.txt','LAERARTILBAKEMELDING.md','IT-DRIFT.md','staff-review-manifest.json','checksums.sha256'].sort();assert.deepEqual(Object.keys(a.files).sort(),expected);
 assert(!Object.keys(a.files).some(p=>/setup|admin|template|teacher-review.html|sound-compare/.test(p)));
 for(const r of a.manifest.files){assert.equal(a.files[r.path].length,r.size);assert.equal(hash(a.files[r.path]),r.sha256)}
 const sums=String(a.files['checksums.sha256']).trim().split('\n');assert.equal(sums.length,expected.length-1);for(const line of sums){const [sha,p]=line.split('  ');assert.equal(hash(a.files[p]),sha)}
 const raw=fs.readFileSync('setup/template.json','utf8'),pin=hash(raw),template=await PK.openTemplate(raw,pin),base=await PK.prepare(template,{...SC.defaults(),schoolName:'Stord kulturskule'});
 for(const locale of ['nn','nb','en']){const html=String(a.files[locale+'.html']),original=Buffer.from(base.files[locale+'.html']).toString();
  assert(html.includes(a.manifest.sourceCommit));assert(html.includes(a.manifest.appCandidateHash));assert(html.includes('id="staffReview"'));assert(html.includes(Staff.CSP));assert(html.indexOf('<meta charset="utf-8">')<1024);
  assert(!html.includes('SCHOOL_PREVIEW_ADAPTER'));assert(!html.includes('id="settingsForm"'));assert.equal(html.match(/<script\b[^>]*>[^]*?<\/script>/g).join('\n'),original.match(/<script\b[^>]*>[^]*?<\/script>/g).join('\n'),'Every actual application script/data remains identical');
 }
 for(const p of PK.policy.templatePaths.filter(p=>p.startsWith('sounds/')))assert.deepEqual(a.files[p],fs.readFileSync('dist/'+p));
 assert.equal(JSON.parse(a.files['school-settings.json']).schemaVersion,6);assert.deepEqual(JSON.parse(a.files['school-settings.json']),{...SC.defaults(),schoolName:'Stord kulturskule'});
 assert(Staff.HEADERS['Content-Security-Policy'].includes("frame-ancestors 'none'"));assert.equal(Staff.HEADERS['Cache-Control'],'private, no-store');
 await assert.rejects(()=>Staff.prepare({...SC.defaults(),themes:['unavailable']}));await assert.rejects(()=>Staff.build('/tmp/disallowed-staff-output'));
 const existing=fs.readFileSync('dist/en.html');try{fs.appendFileSync('dist/en.html','tampered');await assert.rejects(()=>Staff.prepare(),/dist\/template mismatch/)}finally{fs.writeFileSync('dist/en.html',existing)}
 const output=path.resolve('.quality/staff-review/node');await Staff.build(output);const zip=fs.readFileSync(output+'/musikkverkstad-staff-review.zip');assert.equal(fs.readFileSync(output+'/musikkverkstad-staff-review.zip.sha256','utf8').split(' ')[0],hash(zip));
 execFileSync(process.env.PYTHON||'python3',['-c',`import zipfile,sys,pathlib
z=zipfile.ZipFile(sys.argv[1]);assert z.testzip() is None
base=pathlib.Path(sys.argv[2]);assert sorted(z.namelist())==sorted(p.relative_to(base).as_posix() for p in base.rglob('*') if p.is_file())
for n in z.namelist(): assert not n.startswith('/') and '..' not in pathlib.PurePosixPath(n).parts and z.read(n)==(base/n).read_bytes()`,output+'/musikkverkstad-staff-review.zip',output+'/site']);
 await Staff.build(output);assert.deepEqual(fs.readFileSync(output+'/musikkverkstad-staff-review.zip'),zip);
 const restricted=SC.defaults();restricted.themes=['groove'];restricted.formEnabled=false;restricted.programmeEnabled=false;restricted.levels.groove=[2];const r=await Staff.prepare(restricted);assert.deepEqual(JSON.parse(r.files['school-settings.json']),restricted);assert.notEqual(r.manifest.appCandidateHash,a.manifest.appCandidateHash);
 const workflow=fs.readFileSync('.github/workflows/quality.yml','utf8');assert(workflow.includes('!.quality/staff-review/**'));assert(fs.readFileSync('.gitignore','utf8').includes('.quality/'));
 for(const text of ['TA1','TA2','TA3','TA4','TA5','PENDING'])assert(String(a.files['LAERARTILBAKEMELDING.md']).includes(text));
 console.log('PASS staff review: pinned immutable app scripts/audio, provenance/checksums, reproducible safe ZIP, no editor, strict school restrictions and private-output exclusion; hosting/Teams/human validation PENDING.');
})().catch(e=>{console.error(e);process.exitCode=1});
